pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the caller and the timestamp (via vm.warp) and block.number
    function testFuzz_property(address caller, uint256 warpTime, uint256 blockNum) public {
        // admissible domain: caller must be non-zero and not this contract
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));

        // ensure warpTime is a realistic timestamp and bound it to uint32 range to avoid absurd values
        warpTime = bound(warpTime, 1, type(uint32).max);
        // bound block number to a reasonable range
        blockNum = bound(blockNum, 1, 10_000_000);

        // Arrange: ensure caller has 10 ether and set block context
        vm.deal(caller, 10 ether);
        vm.warp(warpTime);
        vm.roll(uint64(blockNum));

        // record previous pastBlockTime
        uint256 prev = c.pastBlockTime();

        // Act: perform the payable fallback call from caller with exactly 10 ether
        vm.prank(caller);
        // call fallback by sending ether to the contract address
        (bool ok, ) = address(c).call{value: 10 ether}("");
        // for the reference contract, the call must succeed only when msg.value==10 ether (we supply exactly)
        // but it may revert if block.timestamp <= prev. We do not assert on ok here; we will assert the invariant below.

        // read new pastBlockTime
        uint256 after = c.pastBlockTime();

        // General invariant: in the correct contract, whenever pastBlockTime is updated by a successful call it must be strictly greater than the previous value.
        // Because we cannot directly know if the call updated it, we check: if after != prev then after must be > prev.
        assertTrue(!(after != prev) || (after > prev));
    }
}

