pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: caller address and a timestamp delta to control block.timestamp progression
    function testFuzz_property(address caller, uint64 dt) public {
        // keep caller non-zero and dt within a wide but practical bound
        vm.assume(caller != address(0));
        dt = uint64(bound(int256(dt), 0, int256(1000))); // allow same-timestamp and small advances

        // deploy a reverting helper that will revert on receive/fallback so any transfer to it fails
        Reverter r = new Reverter();

        // fund caller so it can send 10 ether
        vm.deal(caller, 20 ether);

        // FIRST call: set pastBlockTime to current timestamp via a valid call
        vm.prank(caller);
        vm.warp(block.timestamp + 1); // ensure initial call advances time
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        // ok1 should be true on the reference; mutant may also succeed here

        // prepare second call: route recipient (msg.sender) to the reverter by using a contract that forwards msg.sender?
        // We cannot change msg.sender directly, but we can have caller be the reverter contract by making the reverter call into c.
        // So deploy and fund a Forwarder that in turn calls c while being the msg.sender; but we need the Forwarder to be the one that reverts when paid.
        // Instead, we will have the Reverter itself call c so that if c attempts to transfer to msg.sender (the Reverter), the transfer reverts.

        // fund reverter so it can call
        vm.deal(address(r), 20 ether);

        // Warp time by dt (can be zero) to test both same-timestamp and advanced-timestamp scenarios
        vm.warp(block.timestamp + dt);

        // Have the reverter call c with 10 ether as msg.sender
        vm.prank(address(r));
        (bool ok2, ) = address(c).call{value: 10 ether}("call-from-reverter");

        // The general rule: on the reference contract, ANY call that sends exactly 10 ether will NOT result in c attempting a .transfer to a callee that reverts in the circumstance where block.timestamp did not advance beyond pastBlockTime prior to the transfer; thus, the call initiated by the reverter must not succeed in causing the contract to lose balance due to a transfer to the reverter.
        // We observe c only via its balance. If the reverter-caused transfer happened, c.balance would become 0 (transferred out). On the correct contract this never happens for all inputs; the mutant can cause a transfer to the reverter and thus make c.balance == 0 for some inputs.

        // Assert: c's balance is never zero after the second call (reference preserves funds); the mutant that removes the timestamp check can cause c.balance == 0 for some inputs.
        assertTrue(address(c).balance != 0);
    }
}

// adversarial helper that always reverts on receive/fallback (so any transfer to it will revert)
contract Reverter {
    fallback() external payable {
        revert("i revert");
    }
    receive() external payable {
        revert("i revert");
    }
}

