pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz parameters: caller address and two timestamps and block numbers to simulate two sequential calls.
    // We let the fuzzer choose whether time advances or not and whether the second call occurs at a block number divisible by 15.
    function testFuzz_property(address caller, uint256 t0, uint256 t1, uint256 b0, uint256 b1) public {
        // keep values in sensible ranges
        vm.assume(caller != address(0));
        // bound timestamps to reasonable range
        t0 = bound(t0, 1, type(uint64).max);
        t1 = bound(t1, 1, type(uint64).max);
        // bound block numbers to reasonable range
        b0 = bound(b0, 1, 1000000);
        b1 = bound(b1, 1, 1000000);

        // ensure we can fund the caller
        vm.deal(caller, 20 ether);

        // First call: set timestamp and block.number to t0/b0 and send 10 ether
        vm.warp(uint64(t0));
        vm.roll(uint64(b0));
        vm.prank(caller);
        c.f{value: 10 ether}();

        // record pastBlockTime after first call
        uint256 firstTime = c.pastBlockTime();
        // contract balance after first call should be 10 ether unless transfer happened (only if b0%15==0 and mutant allowed it)
        uint256 balAfterFirst = address(c).balance;

        // Second call: set timestamp and block.number to t1/b1 and send 10 ether
        vm.warp(uint64(t1));
        vm.roll(uint64(b1));
        vm.prank(caller);
        c.f{value: 10 ether}();

        // After second call, read public pastBlockTime and contract balance
        uint256 secondTime = c.pastBlockTime();
        uint256 balAfterSecond = address(c).balance;

        // General rule (single assertion): For the correct contract, if block.timestamp did NOT advance (t1 <= firstTime)
        // then the fallback requires timestamp to be greater so pastBlockTime must remain equal to firstTime and the contract
        // must not have forwarded its balance; thus pastBlockTime == firstTime and balance unchanged between calls.
        // We assert that when t1 <= firstTime, then pastBlockTime is unchanged and balance did not drop to zero.
        // This property holds for the reference C for all inputs; the mutant (which removed the timestamp check)
        // can set pastBlockTime to t1 (even if t1 <= firstTime) and possibly forward the balance when b1%15==0,
        // causing this assertion to fail for some fuzzed inputs.
        if (t1 <= firstTime) {
            assertTrue(secondTime == firstTime && balAfterSecond == balAfterFirst);
        } else {
            // if time advanced, reference may update pastBlockTime and possibly transfer depending on block number;
            // we don't assert anything in that branch to keep property universal for the first branch only.
            assertTrue(true);
        }
    }
}

