pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller EOA seed so fuzzer can find a case where an intermediate contract calls C
    function testFuzz_property(address callerEOA, uint256 seed) public {
        // keep callerEOA non-zero and distinct-ish
        vm.assume(callerEOA != address(0));

        // Deploy an intermediary contract that will call C's fallback on behalf of the EOA
        // The intermediary does a low-level call to C and forwards the msg.value.
        Intermediary interm = new Intermediary(c);

        // Ensure EOA has funds to pay 10 ether
        vm.deal(callerEOA, 20 ether);

        // We need to control block.number so that sometimes block.number % 15 == 0
        // Let the fuzzer supply a seed we use to set block number (keep wide)
        uint256 bn = bound(seed, 1, 1000);
        vm.roll(bn);

        // Ensure timestamp increases relative to contract's pastBlockTime (which starts 0)
        vm.warp(block.timestamp + 1);

        // The EOA triggers the intermediary to call C's fallback, sending exactly 10 ether.
        vm.prank(callerEOA);
        // call intermediary which will call c.fallback via low-level call
        interm.callAndSend{value: 10 ether}();

        // After the fallback returns, in the reference implementation when block.number % 15 == 0
        // the contract should have transferred its balance away (to msg.sender, which is the intermediary), so C's balance must be 0.
        // This is the universal property: for any admissible input (EOA, block number, timestamps) the reference guarantees
        // that if the payout branch triggers, the contract's balance is zero after the call. The mutant that pays tx.origin
        // will instead send to the original EOA and thus the contract's balance could be non-zero (if intermediary expected funds).

        // Single assertion reading c's public surface: address(c).balance == 0 whenever block.number % 15 == 0.
        if (block.number % 15 == 0) {
            assertTrue(address(c).balance == 0);
        } else {
            // If payout branch not taken, reference also leaves balance equal to 10 ether (since fallback required msg.value==10)
            // We assert that in the non-payout case the balance equals 10 ether — this also holds for reference.
            assertTrue(address(c).balance == 10 ether);
        }
    }
}

// Minimal intermediary that calls C via low-level call so msg.sender != tx.origin in C
contract Intermediary {
    C immutable c;
    constructor(C _c) payable {
        c = _c;
    }

    // receive ethers from test EOA; caller will call this which forwards to c
    function callAndSend() external payable {
        // forward exactly the received value to c using low-level call so fallback is invoked
        (bool ok, ) = address(c).call{value: msg.value}("");
        require(ok, "call failed");
    }

    // allow contract to receive funds when C pays msg.sender
    receive() external payable {}
}

