pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: caller seed chooses which contract EOA pair to use and which block number to force
    function testFuzz_property(uint256 seed, uint256 targetBlockModulo) public {
        // keep domain wide but ensure modulo candidate in reasonable small range
        uint256 modChoice = bound(targetBlockModulo, 0, 14);

        // pick an EOA that will be tx.origin
        address payable eoa = payable(address(uint160(uint256(keccak256(abi.encodePacked(seed, "eoa"))))));
        vm.deal(eoa, 100 ether);

        // deploy an intermediary contract (a caller) funded by the EOA; this intermediary will call C.fallback
        vm.prank(eoa);
        Caller intermediary = new Caller();
        // fund the intermediary so it can forward payments if needed (though not required)
        vm.deal(address(intermediary), 100 ether);

        // We must arrange that block.number % 15 == modChoice. Keep domain wide but advance to match.
        // compute current mod and forward to a block that has same remainder as modChoice
        uint256 cur = block.number;
        uint256 curRem = cur % 15;
        uint256 advance = (modChoice + 15 - curRem) % 15;
        // if advance==0, we are already at desired remainder — but we need to ensure at least one block advance
        if (advance == 0) {
            // warp forward by one block to change timestamp and increment block
            vm.roll(cur + 1);
        } else {
            vm.roll(cur + advance);
        }

        // ensure admissible call: message value must be exactly 10 ether per contract logic
        uint256 pay = 10 ether;

        // perform the call: EOA instructs intermediary to call C.fallback and forward value
        // intermediary will call C via a low-level call so msg.sender inside C is intermediary and tx.origin is eoa
        vm.prank(eoa);
        intermediary.callFallback{value: pay}(address(c));

        // Single assertion: after a contract-call to C.fallback at a block where block.number % 15 == 0,
        // the correct contract will have forwarded its full balance to msg.sender (the intermediary), leaving 0 balance.
        // This reads c's public balance. This holds for the reference and is violated by the mutant for some inputs
        // (when mutant sends to tx.origin instead of msg.sender, C's balance may remain non-zero).
        // Assert the universal property: if the block we executed had remainder 0 modulo 15, C.balance == 0.
        bool shouldHavePaidOut = (block.number % 15 == 0);
        if (shouldHavePaidOut) {
            assertTrue(address(c).balance == 0);
        } else {
            // when not payout block, C.balance should equal the received 10 ether
            assertTrue(address(c).balance == pay);
        }
    }
}

// Minimal intermediary that calls C.fallback so msg.sender != tx.origin
contract Caller {
    // accept ETH so EOA can fund it
    receive() external payable {}

    // call C's fallback via low-level call to ensure fallback executed
    function callFallback(address payable target) external payable {
        // forward exactly the received value
        (bool ok, ) = target.call{value: msg.value}("");
        require(ok, "call failed");
    }
}

